 d=H/'ultimate_return_inputs01';need(not d.exists(),'Fresh return input');pp=H/'prepared_ultimate_arrival_partial01/PL02_U.ARC';bp=H/'prepared_hurt_base01/PL00_U.ARC';need(sha(pp.read_bytes())=='3e55b972c007731a8446c8478336c6def303e0dc5ed4ab5d6a52856471327138','Ultimate parent changed');need(sha(bp.read_bytes())=='87e7d1db40c2380815ca2986bc27382db73f718d9c338d2eaad776372a2e257b','Base source changed');a=Archive(pp.read_bytes());b=Archive(bp.read_bytes());target=Image.new('RGBA',(1536,1024));style=Image.new('RGBA',(1536,1024));old=Image.new('RGBA',(1536,1024));crop=(112,96,208,224);rows=[]
