 (d/'prompt.txt').write_text(prompt,'utf8');write(d/'input.json',{'refs':[156],'forms_by_column':['before','after'],'source_layout':{'size':[1536,1024],'grid':[2,1],'native_cell':[96,128],'native_origin':[48,64],'crop':list(crop),'scale':.125},'ultimate_parent':{'path':pp.relative_to(ROOT).as_posix(),'sha256':sha(pp.read_bytes())},'base_pose_source':{'path':bp.relative_to(ROOT).as_posix(),'sha256':sha(bp.read_bytes())},'rows':rows,'new_body_policy':'수용된 새기본형 정면156의 관절/접점으로 Ultimate 의상별 새원화를 제작.원US 전신복원 주장이 아님.','next_derivatives':'157은 역사 가림 예외를 새몸에 복사하지 않는 새정책을 루트와 구분.158은 새156 y−10+원159빛의 실제식 유지.','original_game_art_sent':False,'files':{p.name:sha(p.read_bytes())for p in d.iterdir()if p.is_file()}});print(d)
